                if len(lst) < 2:
                    lst.append(num)
                    # Keep decreasing order for convenience
                    if lst[0] < lst[1]:
                        lst[0], lst[1] = lst[1], lst[0]
                else:
                    # Compare with the smaller of the two (lst[1])
                    if num > lst[1]:
                        if num > lst[0]:
                            lst[1] = lst[0]
                            lst[0] = num
                        else:
                            lst[1] = num
                    # else: not large enough, ignore

        best = -1
        for digit, lst in top_two.items():
            if len(lst) >= 2:
