    def maxProfit(self, prices: List[int], profits: List[int]) -> int:
        n = len(prices)
        max_price = max(prices)

        # Fenwick tree for range maximum query (1-indexed)
        class BIT:
            def __init__(self, size: int):
                self.n = size
                self.tree = [0] * (size + 1)

            def update(self, idx: int, val: int) -> None:
                while idx <= self.n:
                    if val > self.tree[idx]:
                        self.tree[idx] = val
                    idx += idx & -idx

            def query(self, idx: int) -> int:
                res = 0
                while idx > 0:
                    if self.tree[idx] > res:
                        res = self.tree[idx]
                    idx -= idx & -idx
                return res

        # ----- Left side: best profit before i with smaller price -----
        left_best = [0] * n
        left_bit = BIT(max_price)
        for i in range(n):
            p = prices[i]
            if p > 1:                       # there exists a smaller price
                left_best[i] = left_bit.query(p - 1)
            left_bit.update(p, profits[i])

        # ----- Right side: best profit after i with larger price -----
        right_best = [0] * n
        right_bit = BIT(max_price)
        for i in range(n - 1, -1, -1):
            p = prices[i]
            rev = max_price - p + 1        # map larger prices to smaller rev indices
            if rev > 1:                    # there exists a larger original price
                right_best[i] = right_bit.query(rev - 1)
            right_bit.update(rev, profits[i])

        # ----- Combine -----
        ans = -1
        for j in range(n):
            if left_best[j] > 0 and right_best[j] > 0:
                total = left_best[j] + profits[j] + right_best[j]
                if total > ans:
                    ans = total

        return ans

