    def countCompleteSubstrings(self, word: str, k: int) -> int:
        # Split the string into maximal segments where every adjacent pair
        # has alphabet difference <= 2.
        segments = []
        n = len(word)
        i = 0
        while i < n:
            j = i + 1
            while j < n and abs(ord(word[j]) - ord(word[j-1])) <= 2:
                j += 1
            segments.append(word[i:j])
            i = j

        total = 0
        for seg in segments:
            total += self._count_in_segment(seg, k)
        return total

    def _count_in_segment(self, s: str, k: int) -> int:
        n = len(s)
        # Only 26 possible letters, so m (number of distinct characters) is at most 26
        max_m = min(26, n // k)
        res = 0

        for m in range(1, max_m + 1):
            L = k * m               # length of the substring
            freq = [0] * 26
            bad = 0                 # number of characters with freq not 0 and not k

            # Helper to add a character
            def add_char(ch):
                nonlocal bad
                idx = ord(ch) - 97
                old = freq[idx]
                freq[idx] = old + 1
                new = freq[idx]
                if old == 0:
                    if new != k:
                        bad += 1
                elif old == k:
                    bad += 1
                else:
                    if new == k:
                        bad -= 1

            # Helper to remove a character
            def remove_char(ch):
                nonlocal bad
                idx = ord(ch) - 97
                old = freq[idx]
                freq[idx] = old - 1
                new = freq[idx]
                if old == k:
                    if new != 0:
                        bad += 1
                elif old == 0:
                    pass
                else:
                    if new == 0 or new == k:
                        bad -= 1

            # Initialize first window
            for i in range(L):
                add_char(s[i])
            if bad == 0:
                res += 1

            # Slide the window
            for i in range(L, n):
                remove_char(s[i - L])
                add_char(s[i])
                if bad == 0:
                    res += 1

        return res

