class Solution:
    def divisibleTripletCount(self, nums: List[int], d: int) -> int:
        n = len(nums)
        if n < 3:
            return 0

        # Compute remainders modulo d
        rem = [x % d for x in nums]

        # Frequency map for elements to the right of the current middle index j
        # Initially, for j = 1, the right side is indices 2..n-1
        freq = {}
        for k in range(2, n):
            r = rem[k]
            freq[r] = freq.get(r, 0) + 1

        ans = 0
        # j ranges from 1 to n-2 (inclusive) because we need at least one left and one right
        for j in range(1, n-1):
            # For each i < j, count the needed remainder in the right side
            for i in range(j):
                needed = (- (rem[i] + rem[j])) % d
                ans += freq.get(needed, 0)

            # Prepare for next j: remove the element at index j+1 from the right side
            # (since for the next j, this element will become the new middle or left)
            if j + 1 < n:
                r = rem[j+1]
                freq[r] -= 1
                if freq[r] == 0:
                    del freq[r]

        return ans

