class Solution:
    def beautifulIndices(self, s: str, a: str, b: str, k: int) -> List[int]:
        # Helper: KMP pattern search, returns list of starting indices (sorted)
        def kmp_find(text: str, pattern: str) -> List[int]:
            n, m = len(text), len(pattern)
            if m == 0 or n < m:
                return []
            # compute LPS (longest proper prefix which is also suffix)
            lps = [0] * m
            length = 0
            i = 1
            while i < m:
                if pattern[i] == pattern[length]:
                    length += 1
                    lps[i] = length
                    i += 1
                else:
                    if length != 0:
                        length = lps[length - 1]
                    else:
                        lps[i] = 0
                        i += 1
            # search
            res = []
            i = 0  # index in text
            j = 0  # index in pattern
            while i < n:
                if s[i] == pattern[j]:
                    i += 1
                    j += 1
                    if j == m:
                        res.append(i - m)
                        j = lps[j - 1]  # allow overlapping matches
                else:
                    if j != 0:
                        j = lps[j - 1]
                    else:
                        i += 1
            return res

        # Find all occurrences of a and b
        pos_a = kmp_find(s, a)
        pos_b = kmp_find(s, b)

        # If no occurrences of a, result is empty
        if not pos_a or not pos_b:
            return []

        # Two-pointer technique to check condition |j - i| <= k
        result = []
        j = 0
        for i in pos_a:
            # Advance j to the first b index >= i - k
            while j < len(pos_b) and pos_b[j] < i - k:
                j += 1
            # If such b index exists and is within i + k, it's beautiful
            if j < len(pos_b) and pos_b[j] <= i + k:
                result.append(i)

        return result

