class Solution:
    def countMatchingSubarrays(self, nums: List[int], pattern: List[int]) -> int:
        n = len(nums)
        m = len(pattern)
        # Build the diff array of length n-1
        diff = [0] * (n - 1)
        for i in range(n - 1):
            if nums[i+1] > nums[i]:
                diff[i] = 1
            elif nums[i+1] == nums[i]:
                diff[i] = 0
            else:
                diff[i] = -1

        # KMP preprocessing: compute LPS array for pattern
        lps = [0] * m
        j = 0
        for i in range(1, m):
            while j > 0 and pattern[i] != pattern[j]:
                j = lps[j-1]
            if pattern[i] == pattern[j]:
                j += 1
                lps[i] = j

        # KMP search in diff
        count = 0
        j = 0
        for i in range(len(diff)):
            while j > 0 and diff[i] != pattern[j]:
                j = lps[j-1]
            if diff[i] == pattern[j]:
                j += 1
            if j == m:
                # Found a match ending at diff[i]; starting index = i - m + 1
                count += 1
                j = lps[j-1]   # continue looking for overlapping matches

        return count

