class Solution:
    def minimumLevel(self, root: Optional[TreeNode]) -> int:
        if not root:
            return 0  # problem constraints guarantee at least one node, but safe handling

        queue = deque([root])
        min_sum = float('inf')
        min_level = 1
        level = 0

        while queue:
            level += 1
            level_sum = 0
            level_size = len(queue)

            for _ in range(level_size):
                node = queue.popleft()
                level_sum += node.val
                if node.left:
                    queue.append(node.left)
                if node.right:
                    queue.append(node.right)

            if level_sum < min_sum:
                min_sum = level_sum
                min_level = level

        return min_level

