class Solution:
    def numberOfPairs(self, nums1: List[int], nums2: List[int], k: int) -> int:
        # Step 1: find the maximum value of nums1[i] // k among those divisible by k
        max_val = 0
        valid_nums1 = []
        for num in nums1:
            if num % k == 0:
                x = num // k
                if x > max_val:
                    max_val = x
                valid_nums1.append(x)
