            return 0

        # Step 2: frequency of nums2 values that are <= max_val
        freq = [0] * (max_val + 1)
        for num in nums2:
            if num <= max_val:
                freq[num] += 1

        # Step 3: divisor counting using harmonic series
        divisor_count = [0] * (max_val + 1)
        for d in range(1, max_val + 1):
            if freq[d] > 0:
                # add freq[d] to all multiples of d
                for multiple in range(d, max_val + 1, d):
                    divisor_count[multiple] += freq[d]

        # Step 4: sum over valid nums1 values
        total = 0
        for x in valid_nums1:
            total += divisor_count[x]

        return total

