class Solution:
    def countOfPeaks(self, nums: List[int], queries: List[List[int]]) -> List[int]:
        n = len(nums)
        # Fenwick tree (1-indexed)
        bit = [0] * (n + 2)  # enough for indices 1..n

        def _add(idx, delta):
            i = idx + 1  # convert to 1-indexed
            while i <= n:
                bit[i] += delta
                i += i & -i

        def _sum(idx):
            # sum from 0 to idx inclusive (0-indexed)
            i = idx + 1
            s = 0
            while i > 0:
                s += bit[i]
                i -= i & -i
            return s

        def _range_sum(l, r):
            if l > r: return 0
            return _sum(r) - _sum(l-1)

        # is_peak array (boolean) only for indices 1..n-2
        is_peak = [False] * n

        def check_peak(i):
            return 1 <= i <= n-2 and nums[i] > nums[i-1] and nums[i] > nums[i+1]

        # initial build
        for i in range(1, n-1):
            if check_peak(i):
                is_peak[i] = True
                _add(i, 1)

        ans = []
        for q in queries:
            if q[0] == 1:
                l, r = q[1], q[2]
                # three or more elements needed for a peak
                if r - l >= 2:
                    cnt = _range_sum(l+1, r-1)
                else:
                    cnt = 0
                ans.append(cnt)
            else:
                idx, val = q[1], q[2]
                if nums[idx] == val:
                    continue
                nums[idx] = val
                # update possible peaks at idx-1, idx, idx+1
                for i in (idx-1, idx, idx+1):
                    if 1 <= i <= n-2:
                        new_peak = check_peak(i)
                        if new_peak != is_peak[i]:
                            if new_peak:
                                _add(i, 1)
                            else:
                                _add(i, -1)
                            is_peak[i] = new_peak
        return ans

