class Solution:
    def minimumArea(self, grid: List[List[int]]) -> int:
        rows = len(grid)
        cols = len(grid[0])

        # Initialize bounds to opposite extremes
        min_row = rows
        max_row = -1
        min_col = cols
        max_col = -1

        # Scan the grid to find the extreme positions of 1's
        for r in range(rows):
            for c in range(cols):
                if grid[r][c] == 1:
                    if r < min_row:
                        min_row = r
                    if r > max_row:
                        max_row = r
                    if c < min_col:
                        min_col = c
                    if c > max_col:
                        max_col = c

        # Calculate height and width of the bounding rectangle
        height = max_row - min_row + 1
        width = max_col - min_col + 1

        # Area = height * width
        return height * width
